//! Parity vectors from tests/fixtures/channels.csv, generated by oracle/channel_generate.py
//! from the verbatim ACE GameActionChannelList/Index/EnterPkLite sources.
use bace_wire::{ChannelAction, ChannelRequest, WireError, opcode::GameActionType};

fn from_hex(text: &str) -> Vec<u8> {
    text.as_bytes()
        .chunks_exact(2)
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}

fn opcode(name: &str) -> GameActionType {
    match name {
        "ListChannels" => GameActionType::ListChannels,
        "IndexChannels" => GameActionType::IndexChannels,
        other => panic!("unexpected fixture action {other}"),
    }
}

#[test]
fn fixture_rows_match_ace_read_sequences() {
    let mut checked = 0;
    for row in include_str!("fixtures/channels.csv")
        .lines()
        .filter(|line| line.starts_with("case,"))
    {
        let fields: Vec<_> = row.split(',').collect();
        assert_eq!(fields.len(), 5, "{row}");
        let payload = from_hex(fields[2]);
        let consumed: usize = fields[3].parse().unwrap();
        let decoded = ChannelRequest::decode(opcode(fields[1]), &payload, payload.len());
        if fields[4] == "EndOfStream" {
            assert_eq!(decoded, Err(WireError::Truncated), "{row}");
        } else {
            let request = decoded.unwrap_or_else(|error| panic!("{row}: {error:?}"));
            assert_eq!(request.trailing_bytes, payload.len() - consumed, "{row}");
            if let ChannelAction::ListChannels { channel } = request.action {
                assert_eq!(channel.to_string(), fields[4], "{row}");
            } else {
                assert_eq!(fields[4], "none", "{row}");
            }
        }
        checked += 1;
    }
    assert_eq!(checked, 7);
}

#[test]
fn truncated_list_channels_payload_is_rejected_at_every_length() {
    for length in 0..4 {
        assert_eq!(
            ChannelRequest::decode(GameActionType::ListChannels, &[1, 2, 3, 4][..length], 4),
            Err(WireError::Truncated),
            "length {length}"
        );
    }
}

#[test]
fn trailing_bytes_are_reported_not_rejected() {
    let request =
        ChannelRequest::decode(GameActionType::ListChannels, &[7, 0, 0, 0, 9, 9], 6).unwrap();
    assert_eq!(request.action, ChannelAction::ListChannels { channel: 7 });
    assert_eq!(request.trailing_bytes, 2);
    let index = ChannelRequest::decode(GameActionType::IndexChannels, &[1, 0, 0, 0, 0], 5).unwrap();
    assert_eq!(index.action, ChannelAction::IndexChannels);
    assert_eq!(index.trailing_bytes, 5);
}

#[test]
fn oversize_and_unrelated_opcodes_are_rejected() {
    assert_eq!(
        ChannelRequest::decode(GameActionType::ListChannels, &[1, 0, 0, 0], 3),
        Err(WireError::LimitExceeded)
    );
    assert_eq!(
        ChannelRequest::decode(GameActionType::Talk, &[], 0),
        Err(WireError::UnexpectedOpcode(GameActionType::Talk.0))
    );
}
